(()=>{const essay=window.ESSAY_MEMORY_LESSONS["discuss-both-views:39"];if(!essay)throw Error('Missing exact source for discuss-both-views:39');essay.learningSentences=[{"paragraph":0,"index":0,"role":"Background（背景）","english":"In recent years, online communication has become one of the most common ways for people to meet others and maintain social contact.","chinese":"近年來，網上溝通已成為人們認識他人和維持社交聯繫最常見的方式之一。","words":[["In",0,0.1],["recent",0.1,0.24],["years",0.24,0.88],["online",1.26,1.52],["communication",1.52,2.26],["has",2.26,2.96],["become",2.96,3.22],["one",3.22,3.58],["of",3.58,3.68],["the",3.68,3.8],["most",3.8,3.96],["common",3.96,4.32],["ways",4.32,4.7],["for",4.7,5.08],["people",5.08,5.36],["to",5.36,5.6],["meet",5.6,5.78],["others",5.78,6.06],["and",6.4,6.72],["maintain",6.72,7],["social",7,7.54],["contact",7.54,8.1]],"start":0,"end":8.861,"sourceIndices":[0]},{"paragraph":0,"index":1,"role":"Transition（轉折）","english":"While some argue that this has made human relationships stronger by removing barriers of distance, I believe that it has, on balance, made many people more socially isolated.","chinese":"雖然有些人認為，這透過消除距離上的障礙，使人際關係變得更牢固，但我認為，整體而言，這反而使許多人在社交上變得更加孤立。","words":[["While",8.941,9.041],["some",9.041,9.181],["argue",9.181,9.481],["that",9.481,9.761],["this",9.761,10.041],["has",10.041,10.261],["made",10.261,10.501],["human",10.501,10.801],["relationships",10.801,11.521],["stronger",11.521,12.001],["by",12.001,12.421],["removing",12.421,12.741],["barriers",12.741,13.221],["of",13.221,13.521],["distance",13.521,13.781],["I",14.481,14.741],["believe",14.741,15.021],["that",15.021,15.261],["it",15.261,15.381],["has",15.381,15.681],["on",15.741,16.181],["balance",16.181,16.521],["made",16.961,17.181],["many",17.181,17.381],["people",17.381,17.821],["more",17.821,18.061],["socially",18.061,18.521],["isolated",18.521,19.161]],"start":8.781,"end":20.162000000000003,"sourceIndices":[1,2]},{"paragraph":1,"index":0,"role":"Topic Sentence（主題句）","english":"On the one hand, the internet can certainly bring people closer together.","chinese":"一方面，互聯網確實可以拉近人與人之間的距離。","words":[["On",20.242,20.382],["the",20.382,20.482],["one",20.482,20.642],["hand",20.642,21.002],["the",21.422,21.602],["internet",21.602,21.922],["can",21.922,22.242],["certainly",22.242,22.622],["bring",22.622,22.922],["people",22.922,23.262],["closer",23.262,23.562],["together",23.562,23.942]],"start":20.082,"end":24.644000000000002,"sourceIndices":[3]},{"paragraph":1,"index":1,"role":"Supporting Detail 1（支持細節一）","english":"Social media platforms, messaging apps and online communities allow individuals to stay in touch even when they live in different cities or countries.","chinese":"社交媒體平台、即時通訊應用程式和網上社群，使人們即使住在不同城市或國家，也能保持聯絡。","words":[["Social",24.724,25.084],["media",25.084,25.344],["platforms",25.344,25.924],["messaging",26.604,26.944],["apps",26.944,27.344],["and",27.344,27.664],["online",27.664,27.924],["communities",27.924,28.604],["allow",28.604,29.404],["individuals",29.404,29.924],["to",29.924,30.264],["stay",30.264,30.464],["in",30.464,30.644],["touch",30.644,30.904],["even",30.904,31.504],["when",31.504,31.784],["they",31.784,31.924],["live",31.924,32.124],["in",32.124,32.364],["different",32.364,32.564],["cities",32.564,32.944],["or",32.944,33.184],["countries",33.184,33.504]],"start":24.564,"end":34.246,"sourceIndices":[4]},{"paragraph":1,"index":2,"role":"Logic Chain（邏輯鏈）","english":"This is especially valuable for families separated by work, study or migration, as they can share daily experiences almost instantly rather than waiting for occasional visits.","chinese":"這對因工作、學習或移民而分隔兩地的家庭尤其有價值，因為他們可以幾乎即時分享日常經歷，而不必等待偶爾的探訪。","words":[["This",34.326,34.526],["is",34.526,34.686],["especially",34.686,34.986],["valuable",34.986,35.586],["for",35.586,35.986],["families",35.986,36.326],["separated",36.326,36.786],["by",36.786,37.226],["work",37.226,37.566],["study",37.906,38.266],["or",38.266,38.746],["migration",38.746,39.146],["as",40.086,40.186],["they",40.186,40.346],["can",40.346,40.506],["share",40.506,40.766],["daily",40.766,41.006],["experiences",41.006,41.846],["almost",41.846,42.586],["instantly",42.586,43.066],["rather",43.066,43.826],["than",43.826,44.146],["waiting",44.146,44.366],["for",44.366,44.746],["occasional",44.746,45.086],["visits",45.086,45.566]],"start":34.166000000000004,"end":46.301,"sourceIndices":[5]},{"paragraph":1,"index":3,"role":"Supporting Detail 2（支持細節二）","english":"The internet also helps people who feel excluded in their local environment to find others with similar interests.","chinese":"互聯網也幫助那些在本地環境中感到被排斥的人，找到與自己有相似興趣的人。","words":[["The",46.381,46.461],["internet",46.461,46.761],["also",46.761,47.321],["helps",47.321,47.741],["people",47.741,48.121],["who",48.121,48.321],["feel",48.321,48.541],["excluded",48.541,49.061],["in",49.061,49.321],["their",49.321,49.461],["local",49.461,49.681],["environment",49.681,50.281],["to",50.281,50.981],["find",50.981,51.221],["others",51.221,51.561],["with",51.561,51.841],["similar",51.841,52.141],["interests",52.141,52.601]],"start":46.221000000000004,"end":53.429,"sourceIndices":[6]},{"paragraph":1,"index":4,"role":"Example（例子）","english":"For example, a shy student who struggles to make friends at school may feel more confident joining an online group about music, gaming or art.","chinese":"例如，一個在學校難以交朋友的害羞學生，可能會在加入關於音樂、遊戲或藝術的網上群組時感到更有信心。","words":[["For",53.509,53.629],["example",53.629,53.909],["a",54.369,54.509],["shy",54.509,54.689],["student",54.689,55.189],["who",55.189,55.389],["struggles",55.389,55.669],["to",55.669,55.969],["make",55.969,56.089],["friends",56.089,56.409],["at",56.409,56.609],["school",56.609,56.809],["may",56.809,57.449],["feel",57.449,57.709],["more",57.709,57.909],["confident",57.909,58.469],["joining",58.469,58.889],["an",58.889,59.289],["online",59.289,59.489],["group",59.489,59.989],["about",59.989,60.289],["music",60.289,60.669],["gaming",61.189,61.449],["or",61.449,62.009],["art",62.009,62.269]],"start":53.349000000000004,"end":62.945,"sourceIndices":[7]},{"paragraph":1,"index":5,"role":"Conclusion（段落總結）","english":"In this sense, digital communication can act as a bridge between people who might otherwise never meet.","chinese":"從這個意義上說，數位溝通可以在人們之間搭建橋樑，讓一些原本可能永遠不會相遇的人產生聯繫。","words":[["In",63.025,63.125],["this",63.125,63.245],["sense",63.245,63.525],["digital",63.885,64.185],["communication",64.185,64.765],["can",64.765,65.565],["act",65.565,65.825],["as",65.825,66.065],["a",66.065,66.145],["bridge",66.145,66.445],["between",66.445,66.925],["people",66.925,67.305],["who",67.305,67.525],["might",67.525,67.705],["otherwise",67.705,67.965],["never",67.965,68.485],["meet",68.485,68.705]],"start":62.865,"end":69.596,"sourceIndices":[8]},{"paragraph":2,"index":0,"role":"Topic Sentence（主題句）","english":"However, I think the stronger argument is that online socialising often creates a thinner and less satisfying form of connection.","chinese":"然而，我認為更有力的觀點是，網上社交往往創造出一種較薄弱、也較不令人滿足的聯繫形式。","words":[["However",69.676,69.956],["I",70.396,70.496],["think",70.496,70.676],["the",70.676,70.796],["stronger",70.796,71.056],["argument",71.056,71.616],["is",71.616,71.976],["that",71.976,72.136],["online",72.136,72.476],["socialising",72.476,73.436],["often",73.436,74.096],["creates",74.096,74.616],["a",74.616,74.816],["thinner",74.816,75.076],["and",75.406,75.716],["less",75.716,75.936],["satisfying",75.936,76.376],["form",76.376,76.936],["of",76.936,77.156],["connection",77.156,77.376]],"start":69.516,"end":78.217,"sourceIndices":[9]},{"paragraph":2,"index":1,"role":"Supporting Detail 1（支持細節一）","english":"Many people now spend hours scrolling through posts, sending short messages or reacting to photos, but these interactions rarely provide the emotional depth of face-to-face conversation.","chinese":"如今，許多人花數小時瀏覽帖文、發送簡短訊息或回應照片，但這些互動很少能提供面對面交談所具有的情感深度。","words":[["Many",78.297,78.457],["people",78.457,78.797],["now",78.797,79.037],["spend",79.037,79.357],["hours",79.357,79.717],["scrolling",79.717,80.177],["through",80.177,80.557],["posts",80.557,80.817],["sending",81.399,81.639],["short",81.639,81.919],["messages",81.919,82.339],["or",82.839,83.019],["reacting",83.019,83.299],["to",83.299,83.619],["photos",83.619,83.899],["but",84.481,84.561],["these",84.561,84.701],["interactions",84.701,85.321],["rarely",85.321,86.161],["provide",86.161,86.621],["the",86.621,86.941],["emotional",86.941,87.201],["depth",87.201,87.721],["of",87.721,88.201],["face-to-face",88.201,88.821],["conversation",88.821,89.121]],"start":78.137,"end":90.184,"sourceIndices":[10]},{"paragraph":2,"index":2,"role":"Logic Chain（邏輯鏈）","english":"When people become used to communicating through screens, they may gradually lose the habit of meeting friends in person, reading body language, or dealing with awkward but necessary real-life conversations.","chinese":"當人們習慣透過螢幕溝通時，他們可能會逐漸失去親身見朋友、理解肢體語言，以及處理尷尬但必要的現實對話的習慣。","words":[["When",90.264,90.384],["people",90.384,90.604],["become",90.604,91.004],["used",91.004,91.524],["to",91.524,91.784],["communicating",91.784,92.244],["through",92.244,92.724],["screens",92.724,93.084],["they",93.729,93.849],["may",93.849,93.949],["gradually",93.949,94.429],["lose",94.429,94.949],["the",94.949,95.149],["habit",95.149,95.369],["of",95.369,95.669],["meeting",95.669,95.869],["friends",95.869,96.289],["in",96.289,96.509],["person",96.509,96.849],["reading",97.344,97.604],["body",97.604,97.884],["language",97.884,98.364],["or",98.932,99.072],["dealing",99.072,99.312],["with",99.312,99.592],["awkward",99.592,99.912],["but",99.912,100.552],["necessary",100.552,100.912],["real-life",100.912,101.812],["conversations",101.812,102.252]],"start":90.104,"end":103.227,"sourceIndices":[11]},{"paragraph":2,"index":3,"role":"Example（例子）","english":"For instance, a group of friends may sit together in a café while each person is absorbed in their own phone.","chinese":"例如，一群朋友可能一起坐在咖啡店裡，但每個人都沉浸在自己的手機之中。","words":[["For",103.307,103.427],["instance",103.427,103.627],["a",104.307,104.407],["group",104.407,104.627],["of",104.627,104.747],["friends",104.747,105.047],["may",105.047,105.287],["sit",105.287,105.487],["together",105.487,105.787],["in",105.787,106.087],["a",106.087,106.147],["café",106.147,106.467],["while",106.467,107.207],["each",107.207,107.407],["person",107.407,107.907],["is",107.907,108.087],["absorbed",108.087,108.287],["in",108.287,108.827],["their",108.827,108.947],["own",108.947,109.147],["phone",109.147,109.447]],"start":103.147,"end":110.163,"sourceIndices":[12]},{"paragraph":2,"index":4,"role":"Effect（影響）","english":"Although they are physically close, they are socially distant.","chinese":"雖然他們在身體距離上很接近，但在社交上卻彼此疏離。","words":[["Although",110.243,110.483],["they",110.483,110.743],["are",110.743,110.883],["physically",110.883,111.163],["close",111.163,111.603],["they",112.003,112.123],["are",112.123,112.223],["socially",112.223,112.583],["distant",112.583,113.023]],"start":110.083,"end":113.749,"sourceIndices":[13]},{"paragraph":2,"index":5,"role":"Conclusion（段落總結）","english":"Over time, this can make relationships feel more convenient but less meaningful.","chinese":"長遠而言，這可能會使人際關係感覺更方便，卻更缺乏意義。","words":[["Over",113.829,113.929],["time",113.929,114.329],["this",114.729,114.929],["can",114.929,115.129],["make",115.129,115.289],["relationships",115.289,115.769],["feel",115.769,116.309],["more",116.309,116.529],["convenient",116.529,117.009],["but",117.009,117.609],["less",117.609,117.769],["meaningful",117.769,118.169]],"start":113.669,"end":119.205,"sourceIndices":[14]},{"paragraph":3,"index":0,"role":"Reiterating Both Sides（重申雙方觀點）","english":"In conclusion, the internet has undoubtedly made it easier for people to contact one another and form new connections.","chinese":"總結來說，互聯網無疑使人們更容易彼此聯絡，並建立新的關係。","words":[["In",119.285,119.385],["conclusion",119.385,119.765],["the",120.525,120.605],["internet",120.605,120.905],["has",120.905,121.245],["undoubtedly",121.245,121.665],["made",121.665,122.225],["it",122.225,122.325],["easier",122.325,122.625],["for",122.625,123.005],["people",123.005,123.305],["to",123.305,123.505],["contact",123.505,123.885],["one",123.885,124.285],["another",124.285,124.605],["and",124.605,125.045],["form",125.045,125.305],["new",125.305,125.505],["connections",125.505,125.865]],"start":119.125,"end":126.737,"sourceIndices":[15]},{"paragraph":3,"index":1,"role":"Reiterating Opinion（重申立場）","english":"Nevertheless, I believe it has made society more isolated overall because online interaction too often replaces, rather than strengthens, genuine human contact.","chinese":"然而，我認為它整體上使社會變得更加孤立，因為網上互動太常取代真正的人際接觸，而不是加強它。","words":[["Nevertheless",126.817,127.077],["I",127.717,127.837],["believe",127.837,128.117],["it",128.117,128.297],["has",128.297,128.397],["made",128.397,128.617],["society",128.617,129.017],["more",129.017,129.557],["isolated",129.557,129.957],["overall",129.957,130.637],["because",130.637,131.497],["online",131.497,131.797],["interaction",131.797,132.477],["too",132.477,132.917],["often",132.917,133.337],["replaces",133.337,133.717],["rather",134.397,134.777],["than",134.777,135.017],["strengthens",135.017,135.737],["genuine",135.977,136.417],["human",136.417,136.777],["contact",136.777,137.257]],"start":126.657,"end":137.657,"sourceIndices":[16]}];essay.meta={"topic":"網上社交使人更親近還是更孤立","summary":"先承認網絡跨距聯繫家庭與同好的作用，再以短促互動、線下習慣流失及同桌各看手機說明接觸數量不等於關係深度。"};essay.support={"sentences":[{"simple":"In the last few years, talking online has become a very common way to meet people and keep in touch.","synonyms":[{"original":"In recent years","simple":"In the last few years","meaning":"近年"},{"original":"online communication","simple":"talking online","meaning":"網上溝通"},{"original":"maintain social contact","simple":"keep in touch","meaning":"維持聯繫"}],"chunks":["In recent years, online communication has become","one of the most common ways for","people to meet others and maintain social contact."],"simpleChunks":["In the last few years,","talking online has become a very common","way to meet people and keep in touch."]},{"simple":"Some say removing distance makes relationships stronger, but I think, overall, online contact has left many people feeling more alone.","synonyms":[{"original":"removing barriers of distance","simple":"removing distance","meaning":"消除距離障礙"},{"original":"on balance","simple":"overall","meaning":"整體而言"},{"original":"socially isolated","simple":"feeling more alone","meaning":"社交孤立"}],"chunks":["While some argue that this has made","human relationships stronger by removing barriers of distance,","I believe that it has, on balance,","made many people more socially isolated."],"simpleChunks":["Some say removing distance makes relationships stronger,","but I think, overall, online contact has","left many people feeling more alone."]},{"simple":"First, the internet really can help people feel closer.","synonyms":[{"original":"On the one hand","simple":"First","meaning":"一方面"},{"original":"certainly","simple":"really","meaning":"確實"},{"original":"bring people closer together","simple":"help people feel closer","meaning":"拉近距離"}],"chunks":["On the one hand, the internet","can certainly bring people closer together."],"simpleChunks":["First, the internet really can","help people feel closer."]},{"simple":"Social media, message apps and online groups let people keep in touch even when they live far apart.","synonyms":[{"original":"Social media platforms","simple":"Social media","meaning":"社交平台"},{"original":"messaging apps","simple":"message apps","meaning":"通訊程式"},{"original":"online communities","simple":"online groups","meaning":"網上社群"},{"original":"stay in touch","simple":"keep in touch","meaning":"保持聯絡"}],"chunks":["Social media platforms, messaging apps and online communities","allow individuals to stay in touch even","when they live in different cities or countries."],"simpleChunks":["Social media, message apps and online","groups let people keep in touch even","when they live far apart."]},{"simple":"This is very useful for families living apart for work, study or moving countries: they can share daily news almost at once instead of waiting to visit.","synonyms":[{"original":"especially valuable","simple":"very useful","meaning":"尤其有價值"},{"original":"separated","simple":"living apart","meaning":"分隔"},{"original":"migration","simple":"moving countries","meaning":"移民"},{"original":"almost instantly","simple":"almost at once","meaning":"幾乎即時"},{"original":"occasional visits","simple":"waiting to visit","meaning":"偶爾探訪"}],"chunks":["This is especially valuable for families separated by work,","study or migration, as they can","share daily experiences almost instantly","rather than waiting for occasional visits."],"simpleChunks":["This is very useful for families living","apart for work, study or moving countries:","they can share daily news almost at","once instead of waiting to visit."]},{"simple":"The internet also helps people who do not feel welcome where they live find others who like the same things.","synonyms":[{"original":"feel excluded","simple":"do not feel welcome","meaning":"感到被排斥"},{"original":"local environment","simple":"where they live","meaning":"本地環境"},{"original":"similar interests","simple":"like the same things","meaning":"相同興趣"}],"chunks":["The internet also helps people who","feel excluded in their local","environment to find others with similar interests."],"simpleChunks":["The internet also helps people who do","not feel welcome where they live find","others who like the same things."]},{"simple":"For example, a quiet student who finds school friendships hard may feel better joining an online music, game or art group.","synonyms":[{"original":"shy student","simple":"quiet student","meaning":"害羞學生"},{"original":"struggles to make friends","simple":"finds school friendships hard","meaning":"難交朋友"},{"original":"more confident","simple":"feel better","meaning":"更有信心"},{"original":"joining an online group","simple":"joining an online","meaning":"加入網上群組"}],"chunks":["For example, a shy student who","struggles to make friends at school","may feel more confident joining an online","group about music, gaming or art."],"simpleChunks":["For example, a quiet student who finds","school friendships hard may feel better","joining an online music, game or art group."]},{"simple":"In this way, talking online can help people meet others they might never meet otherwise.","synonyms":[{"original":"In this sense","simple":"In this way","meaning":"從此意義"},{"original":"digital communication","simple":"talking online","meaning":"數位溝通"},{"original":"act as a bridge","simple":"help people meet","meaning":"搭橋"},{"original":"otherwise never meet","simple":"never meet otherwise","meaning":"原本不會遇見"}],"chunks":["In this sense, digital communication can act as a","bridge between people who might otherwise never meet."],"simpleChunks":["In this way, talking online can help people","meet others they might never meet otherwise."]},{"simple":"But I think a stronger point is that making friends online often leads to weaker and less happy relationships.","synonyms":[{"original":"However","simple":"But","meaning":"然而"},{"original":"stronger argument","simple":"stronger point","meaning":"更有力論點"},{"original":"online socialising","simple":"making friends online","meaning":"網上社交"},{"original":"thinner","simple":"weaker","meaning":"薄弱"},{"original":"less satisfying","simple":"less happy","meaning":"較不滿足"}],"chunks":["However, I think the stronger argument is","that online socialising often creates a","thinner and less satisfying form of connection."],"simpleChunks":["But I think a stronger point","is that making friends online often","leads to weaker and less happy relationships."]},{"simple":"People may spend hours looking at posts, sending short messages or reacting to pictures, but these small exchanges rarely feel as deep as talking in person.","synonyms":[{"original":"scrolling through posts","simple":"looking at posts","meaning":"瀏覽帖文"},{"original":"reacting to photos","simple":"reacting to pictures","meaning":"回應照片"},{"original":"interactions","simple":"small exchanges","meaning":"互動"},{"original":"emotional depth","simple":"feel as deep","meaning":"情感深度"},{"original":"face-to-face conversation","simple":"talking in person","meaning":"面對面談話"}],"chunks":["Many people now spend hours scrolling through posts,","sending short messages or reacting to photos,","but these interactions rarely provide the","emotional depth of face-to-face conversation."],"simpleChunks":["People may spend hours looking at posts,","sending short messages or reacting to pictures,","but these small exchanges rarely feel","as deep as talking in person."]},{"simple":"When people get used to talking through screens, they may slowly stop meeting friends, noticing body language or having hard but important conversations in real life.","synonyms":[{"original":"become used to","simple":"get used to","meaning":"習慣"},{"original":"communicating through screens","simple":"talking through screens","meaning":"透過螢幕溝通"},{"original":"gradually lose the habit","simple":"slowly stop","meaning":"逐漸失去習慣"},{"original":"reading body language","simple":"noticing body language","meaning":"理解肢體語言"},{"original":"awkward but necessary","simple":"hard but important","meaning":"尷尬卻必要"}],"chunks":["When people become used to communicating through screens,","they may gradually lose the habit of","meeting friends in person, reading body language,","or dealing with awkward but necessary real-life conversations."],"simpleChunks":["When people get used to talking through screens,","they may slowly stop meeting friends,","noticing body language or having hard","but important conversations in real life."]},{"simple":"For example, friends may sit in the same café while each one looks only at their own phone.","synonyms":[{"original":"For instance","simple":"For example","meaning":"例如"},{"original":"absorbed in","simple":"looks only at","meaning":"沉浸於"},{"original":"their own phone","simple":"their own phone","meaning":"自己的手機"}],"chunks":["For instance, a group of friends may","sit together in a café while each","person is absorbed in their own phone."],"simpleChunks":["For example, friends may sit","in the same café while each one","looks only at their own phone."]},{"simple":"They may be close together in the room, but they are far apart as friends.","synonyms":[{"original":"Although","simple":"but","meaning":"雖然"},{"original":"physically close","simple":"close together in the room","meaning":"身體接近"},{"original":"socially distant","simple":"far apart as friends","meaning":"社交疏離"}],"chunks":["Although they are physically close,","they are socially distant."],"simpleChunks":["They may be close together in the room,","but they are far apart as friends."]},{"simple":"After a while, relationships may become easier to manage but feel less important.","synonyms":[{"original":"Over time","simple":"After a while","meaning":"長遠而言"},{"original":"convenient","simple":"easier to manage","meaning":"方便"},{"original":"less meaningful","simple":"less important","meaning":"較缺意義"}],"chunks":["Over time, this can make relationships","feel more convenient but less meaningful."],"simpleChunks":["After a while, relationships may become easier to manage","but feel less important."]},{"simple":"To sum up, the internet certainly makes it easier to contact people and make new friends.","synonyms":[{"original":"In conclusion","simple":"To sum up","meaning":"總結"},{"original":"undoubtedly","simple":"certainly","meaning":"無疑"},{"original":"contact one another","simple":"contact people","meaning":"互相聯絡"},{"original":"form new connections","simple":"make new friends","meaning":"建立新關係"}],"chunks":["In conclusion, the internet has undoubtedly","made it easier for people to contact","one another and form new connections."],"simpleChunks":["To sum up, the internet certainly makes it","easier to contact people and make new friends."]},{"simple":"Still, I think it leaves society more alone because talking online too often takes the place of real contact instead of making it stronger.","synonyms":[{"original":"Nevertheless","simple":"Still","meaning":"然而"},{"original":"more isolated overall","simple":"more alone","meaning":"整體更孤立"},{"original":"replaces","simple":"takes the place of","meaning":"取代"},{"original":"rather than strengthens","simple":"instead of making it stronger","meaning":"而非加強"},{"original":"genuine human contact","simple":"real contact","meaning":"真實人際接觸"}],"chunks":["Nevertheless, I believe it has made society","more isolated overall because online interaction too often replaces,","rather than strengthens, genuine human contact."],"simpleChunks":["Still, I think it leaves society more alone","because talking online too often takes the","place of real contact instead of making it stronger."]}],"intro":[{"type":"quiz","prompt":"作者對網上社交的整體判斷是甚麼？","options":["雖有遠距聯繫好處，整體上卻使許多人更孤立。","網絡完全不能讓分隔家庭保持任何聯絡。","只要訊息數量增加，關係深度便必然提高。","朋友身處同一地方就一定會深入交談。"],"correct":0,"why":"論文權衡的是關係品質，不只是聯絡次數。"},{"type":"multi","prompt":"哪些例子支持文章兩方？","detail":"選兩項，再按「確認」。","options":["分隔家庭可即時分享日常。","同坐咖啡店卻各自看手機。","所有網上群組都禁止共同興趣。","短訊必然比面談更有情感深度。"],"correct":[0,1],"why":"一項支持跨距聯繫，一項展示同處仍疏離。"}],"route":[{"type":"sequence","prompt":"還原四段論證","detail":"區分聯絡方便與關係品質。","items":[{"title":"引言","body":"網上社交普及；承認方便但判整體更孤立。"},{"title":"聯繫收益","body":"遠距家人及本地難找同伴者可保持聯繫。"},{"title":"孤立機制","body":"大量淺互動替代面談與肢體語言；同坐仍各看手機。"},{"title":"結論","body":"承認聯絡容易，仍認真實接觸常被取代。"}],"why":"本文重點是接觸機會與關係品質的區別。"}],"evidence":[{"type":"quiz","prompt":"異地家庭具體得到甚麼便利？","options":["幾乎即時分享日常，而非只等偶爾探訪。","不再需要任何彼此交流或分享日常。","必須每週乘飛機才可以交換訊息。","工作學習或移民都不會令家人分隔。"],"correct":0,"why":"即時分享克服距離。"},{"type":"quiz","prompt":"害羞學生的例子證明甚麼？","options":["興趣群組可連接本地難交朋友的人。","每位學生都必須加入相同的網上群組。","網絡讓所有害羞學生立刻不再害羞。","網上友誼必然完全取代學校友誼。"],"correct":0,"why":"網絡可搭橋，但不保證取代全部線下關係。"},{"type":"quiz","prompt":"作者為何質疑頻繁短訊？","options":["互動次數多，仍可能缺少面談的情感深度。","短訊太慢，不能傳送任何文字或圖片。","每次按讚都必然造成嚴重社交衝突。","所有面對面談話都必然缺少情感。"],"correct":0,"why":"數量與品質不同。"},{"type":"quiz","prompt":"咖啡店例子展示甚麼？","options":["同坐近處仍可能因各看手機而疏離。","坐在同一桌便保證有高品質交流。","手機令朋友永遠不能進入任何咖啡店。","所有網上群組都不容許朋友見面。"],"correct":0,"why":"物理接近不保證社交接近。"}],"logic":[{"type":"sequence","prompt":"網絡如何拉近人","detail":"區分聯絡方便與關係品質。","items":[{"title":"工具","body":"社交平台、訊息程式及網上群組。"},{"title":"遠距","body":"分隔家人幾乎即時分享生活。"},{"title":"排斥","body":"本地難交朋友者找到相同興趣者。"},{"title":"概括","body":"網絡搭起原本不會相遇者的橋樑。"}],"why":"先公平承認連結作用。"},{"type":"sequence","prompt":"為何仍可能更孤立","detail":"區分聯絡方便與關係品質。","items":[{"title":"頻率","body":"短訊按讚及瀏覽花大量時間。"},{"title":"品質","body":"淺互動較少面談的情感深度。"},{"title":"習慣","body":"線下見面與理解肢體語言漸少。"},{"title":"結論","body":"網上交流取代而非加強真實接觸。"}],"why":"解釋取代機制而非只宣稱孤立。"}],"structures":[{"id":"model-essay-39-ielts-discuss-both-views-frame-01","frame":"In recent years, [普及的溝通方式] has become one of the most common ways for people to [社交用途].","meaning":"網上交流已成認識和聯繫他人的常見途徑。","usage":"當引言要交代一種近年普及的社會行為時。","source":{"paragraph":1,"sentence":1},"parts":[{"text":"In recent years, ","kind":"link","label":"句型固定部分"},{"text":"online communication","kind":"slot","label":"普及的溝通方式"},{"text":" has become one of the most common ways for people to ","kind":"link","label":"句型固定部分"},{"text":"meet others and maintain social contact","kind":"slot","label":"社交用途"},{"text":".","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In recent years, video calling has become one of the most common ways for people to meet others and maintain social contact.","On the one hand, video calling can certainly bring people closer together.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","In conclusion, video calls has undoubtedly made it easier for people to contact one another and form new connections."],"correct":0,"explanations":["這句現在完成式交代近期變化，用法與原文一致。","這句On the one hand 公平開首方；它並非本題要辨認的句型及功能。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句undoubtedly 承認對方的真實收益；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-02","frame":"While some argue that [好處], I believe that [整體壞處]","meaning":"作者承認跨距聯繫好處，總體仍認為更孤立。","usage":"當引言要承認一項好處，仍作相反的整體判斷時。","source":{"paragraph":1,"sentence":2},"parts":[{"text":"While some argue that ","kind":"link","label":"句型固定部分"},{"text":"this has made human relationships stronger by removing barriers of distance","kind":"slot","label":"好處"},{"text":", I believe that ","kind":"link","label":"句型固定部分"},{"text":"it has, on balance, made many people more socially isolated.","kind":"slot","label":"整體壞處"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["While some argue that this has made human relationships stronger by making daily contact easier, I believe that it has, on balance, made many people more socially isolated.","On the one hand, video calling can certainly bring people closer together.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句While 作讓步而 on balance 定權衡，用法與原文一致。","這句On the one hand 公平開首方；它並非本題要辨認的句型及功能。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-03","frame":"On the one hand, [媒介] can certainly bring people closer together","meaning":"先承認網絡可拉近距離。","usage":"當第一方的說法確有根據，需先公平承認時。","source":{"paragraph":2,"sentence":1},"parts":[{"text":"On the one hand, ","kind":"link","label":"句型固定部分"},{"text":"the internet","kind":"slot","label":"可能拉近人的媒介"},{"text":" can certainly bring people closer together.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["On the one hand, video calling can certainly bring people closer together.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Many people now spend hours sending emojis, liking posts or sharing photos, but these interactions rarely provide the emotional depth of face-to-face conversation.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句On the one hand 公平開首方，用法與原文一致。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句but 反轉數量多等於深度足的假設；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-04","frame":"[工具] allow individuals to stay in touch even when [距離]","meaning":"通訊工具讓異地的人保持聯絡。","usage":"當要以多個具體工具支持一項溝通功能時。","source":{"paragraph":2,"sentence":2},"parts":[{"text":"Social media platforms, messaging apps and online communities","kind":"slot","label":"工具"},{"text":" allow individuals to stay in touch even when ","kind":"link","label":"句型固定部分"},{"text":"they live in different cities or countries.","kind":"slot","label":"距離"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Video calls, group chats and shared photo albums allow individuals to stay in touch even when they live in different cities or countries.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Many people now spend hours sending emojis, liking posts or sharing photos, but these interactions rarely provide the emotional depth of face-to-face conversation.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句even when 指遠距離仍可聯繫，用法與原文一致。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句but 反轉數量多等於深度足的假設；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-05","frame":"This is especially valuable for [群體], as [即時好處] rather than [舊做法]","meaning":"分隔家庭可即時分享日常，而不用等待探訪。","usage":"當你要指出同一便利對某個群體特別重要時。","source":{"paragraph":2,"sentence":3},"parts":[{"text":"This is especially valuable for ","kind":"link","label":"句型固定部分"},{"text":"families separated by work, study or migration","kind":"slot","label":"群體"},{"text":", as ","kind":"link","label":"句型固定部分"},{"text":"they can share daily experiences almost instantly","kind":"slot","label":"即時好處"},{"text":" rather than ","kind":"link","label":"句型固定部分"},{"text":"waiting for occasional visits.","kind":"slot","label":"舊做法"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["This is especially valuable for friends separated by work or travel, as they can share daily experiences almost instantly rather than waiting for occasional visits.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Many people now spend hours sending emojis, liking posts or sharing photos, but these interactions rarely provide the emotional depth of face-to-face conversation.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句as 解釋特別受益的原因，用法與原文一致。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句but 反轉數量多等於深度足的假設；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-06","frame":"The internet also helps [群體] to find others with similar interests","meaning":"本地感排斥者可找志同道合者。","usage":"當你要補充一項服務對較難接觸同伴的人有用時。","source":{"paragraph":2,"sentence":4},"parts":[{"text":"The internet also helps ","kind":"link","label":"句型固定部分"},{"text":"people who feel excluded in their local environment","kind":"slot","label":"線下較難找到同伴的人"},{"text":" to find others with similar interests.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["The internet also helps people who live in small towns to find others with similar interests.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Many people now spend hours sending emojis, liking posts or sharing photos, but these interactions rarely provide the emotional depth of face-to-face conversation.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句also 引入第二種受益者，用法與原文一致。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句but 反轉數量多等於深度足的假設；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-07","frame":"For example, [人物] may feel more confident joining [合適群體]","meaning":"害羞學生可在網上興趣群組更有信心。","usage":"當你要用一個具體人物展示普遍好處如何發生時。","source":{"paragraph":2,"sentence":5},"parts":[{"text":"For example, ","kind":"link","label":"句型固定部分"},{"text":"a shy student who struggles to make friends at school","kind":"slot","label":"人物"},{"text":" may feel more confident joining ","kind":"link","label":"句型固定部分"},{"text":"an online group about music, gaming or art.","kind":"slot","label":"合適群體"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["For example, a new student who struggles to make friends at school may feel more confident joining an online group about music, gaming or art.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Many people now spend hours sending emojis, liking posts or sharing photos, but these interactions rarely provide the emotional depth of face-to-face conversation.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句For example 把弱聯繫群體具體化，用法與原文一致。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句but 反轉數量多等於深度足的假設；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-08","frame":"In this sense, [媒介] can act as a bridge between people who might otherwise never meet","meaning":"數位溝通可讓原本不會相遇的人相識。","usage":"當舉例後要概括一種媒介的連接作用時。","source":{"paragraph":2,"sentence":6},"parts":[{"text":"In this sense, ","kind":"link","label":"句型固定部分"},{"text":"digital communication","kind":"slot","label":"搭橋的媒介"},{"text":" can act as a bridge between people who might otherwise never meet.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In this sense, online hobby groups can act as a bridge between people who might otherwise never meet.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Many people now spend hours sending emojis, liking posts or sharing photos, but these interactions rarely provide the emotional depth of face-to-face conversation.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句In this sense 概括跨人群連結，用法與原文一致。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句but 反轉數量多等於深度足的假設；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-09","frame":"However, I think the stronger argument is that [方式] creates [較弱聯繫]","meaning":"作者認為網上社交常更薄弱、不滿足。","usage":"當你要從公平承認的好處轉到自己認為更強的反論時。","source":{"paragraph":3,"sentence":1},"parts":[{"text":"However, I think the stronger argument is that ","kind":"link","label":"句型固定部分"},{"text":"online socialising often","kind":"slot","label":"方式"},{"text":" creates ","kind":"link","label":"句型固定部分"},{"text":"a thinner and less satisfying form of connection.","kind":"slot","label":"較弱聯繫"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","On the one hand, video calling can certainly bring people closer together.","Video calls, group chats and shared photo albums allow individuals to stay in touch even when they live in different cities or countries.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句However 加 stronger argument 轉作者重點，用法與原文一致。","這句On the one hand 公平開首方；它並非本題要辨認的句型及功能。","這句even when 指遠距離仍可聯繫；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-10","frame":"Many people now spend hours [頻繁的網上行為], but these interactions rarely provide [缺少的情感深度].","meaning":"大量簡短互動缺少面對面情感深度。","usage":"當要區分聯繫的次數與關係的深度時。","source":{"paragraph":3,"sentence":2},"parts":[{"text":"Many people now spend hours ","kind":"link","label":"句型固定部分"},{"text":"scrolling through posts, sending short messages or reacting to photos","kind":"slot","label":"頻繁的網上行為"},{"text":", but these interactions rarely provide ","kind":"link","label":"句型固定部分"},{"text":"the emotional depth of face-to-face conversation","kind":"slot","label":"缺少的情感深度"},{"text":".","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Many people now spend hours sending emojis, liking posts or sharing photos, but these interactions rarely provide the emotional depth of face-to-face conversation.","Video calls, group chats and shared photo albums allow individuals to stay in touch even when they live in different cities or countries.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句but 反轉數量多等於深度足的假設，用法與原文一致。","這句even when 指遠距離仍可聯繫；它並非本題要辨認的句型及功能。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-11","frame":"When people become used to [方式], they may gradually lose the habit of [線下能力]","meaning":"長期透過螢幕可削弱線下相處習慣。","usage":"當你要指出長期習慣可能替代另一項必要能力時。","source":{"paragraph":3,"sentence":3},"parts":[{"text":"When people become used to ","kind":"link","label":"句型固定部分"},{"text":"communicating through screens","kind":"slot","label":"方式"},{"text":", they may gradually lose the habit of ","kind":"link","label":"句型固定部分"},{"text":"meeting friends in person, reading body language, or dealing with awkward but necessary real-life conversations.","kind":"slot","label":"線下能力"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["When people become used to texting in short messages, they may gradually lose the habit of meeting friends in person, reading body language, or dealing with awkward but necessary real-life conversations.","Video calls, group chats and shared photo albums allow individuals to stay in touch even when they live in different cities or countries.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句When 加 may 演繹逐漸發生的風險，用法與原文一致。","這句even when 指遠距離仍可聯繫；它並非本題要辨認的句型及功能。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-12","frame":"For instance, [同處的人] may sit together in [同處地點] while each person is absorbed in [各自注視的事物].","meaning":"朋友同坐咖啡店卻各看自己的手機。","usage":"當你要用可觀察的日常場景呈現抽象疏離時。","source":{"paragraph":3,"sentence":4},"parts":[{"text":"For instance, ","kind":"link","label":"句型固定部分"},{"text":"a group of friends","kind":"slot","label":"同處的人"},{"text":" may sit together in ","kind":"link","label":"句型固定部分"},{"text":"a café","kind":"slot","label":"同處地點"},{"text":" while each person is absorbed in ","kind":"link","label":"句型固定部分"},{"text":"their own phone","kind":"slot","label":"各自注視的事物"},{"text":".","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["For instance, two classmates may sit together in a café while each person is absorbed in their own phone.","Video calls, group chats and shared photo albums allow individuals to stay in touch even when they live in different cities or countries.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句while 對照同處與各自看手機，用法與原文一致。","這句even when 指遠距離仍可聯繫；它並非本題要辨認的句型及功能。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-13","frame":"Although [空間接近], [社交距離遠]","meaning":"身體接近仍可社交疏離。","usage":"當你要用 Although 對照表面接近與實際關係時。","source":{"paragraph":3,"sentence":5},"parts":[{"text":"Although ","kind":"link","label":"句型固定部分"},{"text":"they are physically close","kind":"slot","label":"空間接近"},{"text":", ","kind":"link","label":"句型固定部分"},{"text":"they are socially distant.","kind":"slot","label":"社交距離遠"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Although they are sitting nearby, they are socially distant.","Video calls, group chats and shared photo albums allow individuals to stay in touch even when they live in different cities or countries.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句Although 把物理距離和關係品質分開，用法與原文一致。","這句even when 指遠距離仍可聯繫；它並非本題要辨認的句型及功能。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-14","frame":"Over time, this can make relationships feel [便利] but [缺少意義]","meaning":"關係更方便，卻可能更缺意義。","usage":"當你要比較某改變帶來的便利與其品質代價時。","source":{"paragraph":3,"sentence":6},"parts":[{"text":"Over time, this can make relationships feel ","kind":"link","label":"句型固定部分"},{"text":"more convenient","kind":"slot","label":"便利"},{"text":" but ","kind":"link","label":"句型固定部分"},{"text":"less meaningful.","kind":"slot","label":"缺少意義"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Over time, this can make relationships feel easier to maintain but less meaningful.","Video calls, group chats and shared photo albums allow individuals to stay in touch even when they live in different cities or countries.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句but 總結便利與意義的取捨，用法與原文一致。","這句even when 指遠距離仍可聯繫；它並非本題要辨認的句型及功能。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-15","frame":"In conclusion, [工具] has made contact and new connections easier","meaning":"結論先承認聯繫變容易。","usage":"當結論要先保留反方確實成立的好處時。","source":{"paragraph":4,"sentence":1},"parts":[{"text":"In conclusion, ","kind":"link","label":"句型固定部分"},{"text":"the internet","kind":"slot","label":"促進聯絡的工具"},{"text":" has undoubtedly made it easier for people to contact one another and form new connections.","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In conclusion, video calls has undoubtedly made it easier for people to contact one another and form new connections.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Many people now spend hours sending emojis, liking posts or sharing photos, but these interactions rarely provide the emotional depth of face-to-face conversation.","Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact."],"correct":0,"explanations":["這句undoubtedly 承認對方的真實收益，用法與原文一致。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句but 反轉數量多等於深度足的假設；它並非本題要辨認的句型及功能。","這句because 加 replaces rather than strengthens 定核心機制；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"},{"id":"model-essay-39-ielts-discuss-both-views-frame-16","frame":"Nevertheless, I believe [整體判斷] because [可能取代接觸的方式] too often replaces, rather than strengthens, [本應加強的關係].","meaning":"聯繫增加不保證不孤立；網上互動可能取代真實接觸。","usage":"當結論要區分補充一種好處與取代更重要的活動時。","source":{"paragraph":4,"sentence":2},"parts":[{"text":"Nevertheless, I believe ","kind":"link","label":"句型固定部分"},{"text":"it has made society more isolated overall","kind":"slot","label":"整體判斷"},{"text":" because ","kind":"link","label":"句型固定部分"},{"text":"online interaction","kind":"slot","label":"可能取代接觸的方式"},{"text":" too often replaces, rather than strengthens, ","kind":"link","label":"句型固定部分"},{"text":"genuine human contact","kind":"slot","label":"本應加強的關係"},{"text":".","kind":"link","label":"句型固定部分"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Nevertheless, I believe it has made society more isolated overall because brief digital exchange too often replaces, rather than strengthens, genuine human contact.","However, I think the stronger argument is that brief group-chat contact often creates a thinner and less satisfying form of connection.","Many people now spend hours sending emojis, liking posts or sharing photos, but these interactions rarely provide the emotional depth of face-to-face conversation.","In conclusion, video calls has undoubtedly made it easier for people to contact one another and form new connections."],"correct":0,"explanations":["這句because 加 replaces rather than strengthens 定核心機制，用法與原文一致。","這句However 加 stronger argument 轉作者重點；它並非本題要辨認的句型及功能。","這句but 反轉數量多等於深度足的假設；它並非本題要辨認的句型及功能。","這句undoubtedly 承認對方的真實收益；它並非本題要辨認的句型及功能。"],"patternType":"reviewed"}],"transfer":[{"prompt":"哪句支持網絡聯繫的一方？","context":"異地家人每天用視像通話分享近況。","question":"哪句支持網絡聯繫的一方？","options":["跨越距離的即時交流可維繫分隔家人的關係。","家人能即時交談，關係仍主要取決於共同居住。","視像可看到表情，但不足以分享日常生活近況。","每天通話讓家人方便安排探訪，分隔時則少有交流。"],"correct":0,"explanations":["克服距離是確實收益。","相隔兩地也可藉即時分享維繫關係。","視像正能分享日常生活。","探訪可安排，但此例重點是分隔時的交流。"],"why":"克服距離是確實收益。","sourceSentenceIndices":[3,4],"modelLink":"distance barrier removed。"},{"prompt":"哪句能轉用搭橋的邏輯？","context":"學生身邊沒有人喜歡同一種音樂。","question":"哪句能轉用搭橋的邏輯？","options":["網上興趣群組可幫他找到原本難以認識的同伴。","網上群組可提供新歌推薦，認識同伴仍靠同校活動。","學生能找到同好，但群組的作用只在購買音樂。","網上聊天方便，興趣相同者卻難以在其中結識。"],"correct":0,"explanations":["相同興趣跨本地限制。","網上群組有助找同好，不限同校活動。","找到同伴不只用於購買音樂。","共同興趣正是群組結識新人的原因。"],"why":"相同興趣跨本地限制。","sourceSentenceIndices":[5,6,7],"modelLink":"bridge otherwise never meet。"},{"prompt":"哪句分析數量與品質差別？","context":"一人每天收到很多按讚，卻仍感到孤單。","question":"哪句分析數量與品質差別？","options":["網上回應雖多，仍可能缺少深入交談的支持。","按讚雖短暫，數量夠多便能代替深入交談。","孤單感主要取決於發文頻率，與支持深度無關。","網上回應多，便可推定朋友已理解他的處境。"],"correct":0,"explanations":["互動量不等於情感深度。","數量不能代替深入支持。","孤獨與交流質素有關。","按讚不能證明朋友理解處境。"],"why":"互動量不等於情感深度。","sourceSentenceIndices":[8,9],"modelLink":"thin connection despite frequency。"},{"prompt":"哪句準確解釋例子？","context":"四位朋友同桌用餐，卻全程只看手機。","question":"哪句準確解釋例子？","options":["他們在空間上很近，互動上卻可能互相疏離。","朋友能同桌吃飯，因此日後仍可再補回當晚交流。","看手機可分享資訊，但未注意彼此當下的感受。","四人距離很近，故能由沉默直接建立互相信任。"],"correct":0,"explanations":["物理接近不等於社交接近。","日後可談，也不代表當晚有互動。","只看手機未必有注意朋友。","同桌距離近，不等於深度交流。"],"why":"物理接近不等於社交接近。","sourceSentenceIndices":[11,12],"modelLink":"physically close socially distant。"},{"prompt":"哪句補足可能的機制？","context":"作文只說「網絡令社會孤立」。","question":"哪句補足可能的機制？","options":["過度依賴螢幕或使人漸少親身見面和理解表情。","長時間用網絡可減少外出，卻不影響理解表情。","網上聯絡多了，親身見面次數應由平台決定。","螢幕交流能帶來資訊，孤立主要來自網速不穩。"],"correct":0,"explanations":["習慣替代需說清楚。","長用螢幕也可能削弱面對面理解。","平台不會自動決定人是否見面。","網速與原文的親身關係機制不同。"],"why":"習慣替代需說清楚。","sourceSentenceIndices":[9,10],"modelLink":"screen habit replaces meetings。"},{"prompt":"哪句可借用本文的比較尺度？","context":"另一題問遠距辦公是否促進團隊合作。","question":"哪句可借用本文的比較尺度？","options":["比較聯絡方便程度，亦要看互信與討論深度。","可比較訊息數量與會議成本，互信則留待考核。","聯絡更快捷便是合作改善，討論深度可略過。","同處辦公可讓員工見面，工作成果則無需評估。"],"correct":0,"explanations":["方便與品質分開衡量。","互信不能只留到考核時才看。","速度與討論深度是不同維度。","工作成果仍需評估。"],"why":"方便與品質分開衡量。","sourceSentenceIndices":[3,9,12],"modelLink":"access versus connection quality。"},{"prompt":"哪句更公平地呈現文章？","context":"有人認為網上溝通全無好處。","question":"哪句更公平地呈現文章？","options":["它可連異地人與同好，只是未必能替代深入面談。","網上溝通可連結異地人，故面談只用於緊急情況。","找到興趣群組可減孤單，可以少維持線下友誼。","網絡有方便之處，深入交流則主要靠按讚數量。"],"correct":0,"explanations":["承認收益而指出限制。","線下面談仍有重要的深入支持作用。","找到同好不代表可停止其他友誼。","按讚數量不能代替深入交流。"],"why":"承認收益而指出限制。","sourceSentenceIndices":[3,5,14,15],"modelLink":"concede contact advantage。"},{"prompt":"哪句指出長期風險？","context":"某人偏好短訊，漸漸不願處理尷尬面談。","question":"哪句指出長期風險？","options":["長期習慣螢幕交流或削弱處理線下對話的能力。","短訊可避免尷尬，但難談話題可交給別人處理。","他不願面談是性格問題，與長期螢幕習慣無關。","線下對話需要練習，短訊卻可直接取代該能力。"],"correct":0,"explanations":["線下能力或流失。","把難談話題交他人，未解決自己的能力退化。","習慣螢幕可能影響面談能力。","短訊不能直接替代肢體與面談技能。"],"why":"線下能力或流失。","sourceSentenceIndices":[10],"modelLink":"loss of real-life habits。"},{"prompt":"哪句最完整？","context":"文章結論要同時承認方便與指出孤立。","question":"哪句最完整？","options":["聯絡雖更方便，但真實接觸若被取代仍可更孤立。","聯絡更方便，故孤立感主要只由朋友數量決定。","真實接觸若減少，網上頻繁回應仍可充分補足。","網絡可能帶來孤立，結論因此不必談方便之處。"],"correct":0,"explanations":["讓步與核心機制兼有。","朋友數量不是孤立的唯一原因。","頻繁網上回應未必補足真實接觸。","結論須承認網絡聯絡的便利。"],"why":"讓步與核心機制兼有。","sourceSentenceIndices":[14,15],"modelLink":"replaces rather than strengthens。"},{"prompt":"哪句最合文章的限定說法？","context":"朋友每週視像聯絡，也每月親身相聚。","question":"哪句最合文章的限定說法？","options":["網上交流可補充真實接觸，問題在於它被用來取代。","視像能維繫友誼，親身相聚則可改為節日活動。","定期面談有益，網上交流只適合安排見面時間。","兩種方式可並存，卻未分辨補充與取代的差別。"],"correct":0,"explanations":["關鍵是補充還是取代。","每月相聚也是重要安排，不只節日。","網上交流也能在分隔時維持友誼。","核心是補充有益、完全取代有風險。"],"why":"關鍵是補充還是取代。","sourceSentenceIndices":[15],"modelLink":"supplement versus replace。"}],"mediumExtras":[]};})();
